begin;
create extension if not exists pgtap with schema extensions;
insert into auth.users(id,email) values ('d1111111-1111-4111-8111-111111111111','startup@carez.invalid');
insert into public.companies(id,name) values ('d2222222-2222-4222-8222-222222222222','Startup fixture');
insert into public.profiles(id,company_id,full_name,role) values ('d1111111-1111-4111-8111-111111111111','d2222222-2222-4222-8222-222222222222','Startup Owner','owner');
insert into public.customers(id,company_id,name,contact_name,email) values ('d3333333-3333-4333-8333-333333333333','d2222222-2222-4222-8222-222222222222','Startup Customer','GC Contact','gc@example.invalid');
insert into public.projects(id,company_id,customer_id,job_number,name,address,city,state,contract_value,sales_tax_exempt) values ('d4444444-4444-4444-8444-444444444444','d2222222-2222-4222-8222-222222222222','d3333333-3333-4333-8333-333333333333','START-01','Startup Fixture Job','1 Main St','Tacoma','WA',1000,true);
select set_config('request.jwt.claim.sub','d1111111-1111-4111-8111-111111111111',true);
set local role authenticated;
select extensions.plan(9);
select extensions.ok(to_regclass('public.project_award_records') is not null,'accepted award record is source-controlled');
select extensions.ok((select relrowsecurity from pg_class where oid='public.project_closeouts'::regclass),'closeout checklist enforces RLS');
insert into public.project_award_records(company_id,project_id,agreement_number,original_contract_value,status) values ('d2222222-2222-4222-8222-222222222222','d4444444-4444-4444-8444-444444444444','AWD-FIXTURE',1000,'accepted');
select extensions.ok((select agreement_captured from public.project_job_readiness_summary where project_id='d4444444-4444-4444-8444-444444444444'),'job readiness sees accepted agreement evidence');
select extensions.ok((select job_ready from public.project_job_readiness_summary where project_id='d4444444-4444-4444-8444-444444444444'),'tax-exempt project with accepted agreement is job-ready');
insert into public.project_startup_items(company_id,project_id,title,detail) values ('d2222222-2222-4222-8222-222222222222','d4444444-4444-4444-8444-444444444444','Confirm access','Confirm site access with customer.');
select extensions.is((select manual_open from public.project_startup_readiness where project_id='d4444444-4444-4444-8444-444444444444'),1,'startup readiness counts open manual confirmations');
select extensions.ok((select readiness_status from public.project_startup_readiness where project_id='d4444444-4444-4444-8444-444444444444')='needs_setup','startup readiness remains held without a scheduled crew plan');
insert into public.project_closeouts(company_id,project_id) values ('d2222222-2222-4222-8222-222222222222','d4444444-4444-4444-8444-444444444444');
update public.project_closeouts set documents_complete=true,closeout_notes='Fixture checklist' where project_id='d4444444-4444-4444-8444-444444444444';
select extensions.ok((select documents_complete from public.project_closeouts where project_id='d4444444-4444-4444-8444-444444444444'),'closeout checklist preserves owner updates');
select extensions.ok(has_table_privilege('authenticated','public.project_startup_items','INSERT'),'owner can maintain startup confirmations');
select extensions.ok(not has_table_privilege('anon','public.project_closeouts','SELECT'),'anonymous cannot read closeout facts');
reset role;
select * from extensions.finish();
rollback;
